// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 warpTs) public {
        vm.assume(warpTs > 0);
        vm.assume(warpTs < type(uint64).max);

        vm.deal(caller, 20 ether);

        uint256 oldPast = c.pastBlockTime();

        uint256 newTs = warpTs;
        if (newTs <= oldPast) {
            newTs = oldPast + 1;
        }

        vm.warp(newTs);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        vm.assume(ok);

        assertTrue(c.pastBlockTime() == newTs + 1);
    }
}
